/**
 * CCAR-P Study Page - bilingual lessons by blueprint domain → objective
 * Data: window.CCARP_LESSONS (CCAR-P/lessons/lessons.js, generated by build_ccarp.py)
 */

(function () {
  "use strict";

  const LESSONS = window.CCARP_LESSONS || [];
  const MANIFEST = window.QUIZ_MANIFEST_CCARP || [];
  const PROGRESS_KEY = "ccarp_learn_done";
  const PRACTICE_SIZE = 5;

  // Thông tin kỳ thi lấy từ CCAR-P Exam Guide v1.0 (Section 5, 6, 8)
  const EXAM_FACTS = [
    { val: "63", lbl: "Số câu hỏi" },
    { val: "120 phút", lbl: "Thời gian (~1m54s/câu)" },
    { val: "720 / 1000", lbl: "Điểm đạt (thang 100–1.000)" },
    { val: "$175", lbl: "Lệ phí thi" },
    { val: "12 tháng", lbl: "Hiệu lực chứng chỉ" },
    { val: "Pearson VUE", lbl: "Online proctored / test center" }
  ];

  const STUDY_STEPS = [
    {
      en: "Study the blueprint and self-assess against every objective — each lesson below is one objective.",
      vi: "Nắm blueprint và tự đánh giá theo từng objective — mỗi bài học bên dưới tương ứng một objective."
    },
    {
      en: "Read the English text first (the exam uses these exact terms), then check the Vietnamese translation.",
      vi: "Đọc phần tiếng Anh trước (đề thi dùng đúng các thuật ngữ này), sau đó đối chiếu bản dịch tiếng Việt."
    },
    {
      en: "Finish each lesson with the topic practice questions, then take full 63-item, 120-minute mock exams.",
      vi: "Kết thúc mỗi bài bằng phần luyện câu hỏi theo chủ đề, sau đó làm đề thi thử đầy đủ 63 câu / 120 phút."
    },
    {
      en: "Multiple-response items always state how many answers to select — read that number before choosing.",
      vi: "Câu chọn nhiều đáp án luôn ghi rõ số đáp án cần chọn — đọc kỹ con số này trước khi chọn."
    }
  ];

  const SAMPLES = [
    {
      domain: "Domain 3 — Integration",
      q: "A team exposes a customer-support agent that can read tickets, draft replies, issue refunds, and delete user accounts. Support staff only ever need to read tickets and draft replies. Applying least-privilege principles, which change best reduces risk?",
      q_vi: "Một nhóm cung cấp agent hỗ trợ khách hàng có thể đọc ticket, soạn phản hồi, hoàn tiền và xóa tài khoản người dùng. Nhân viên hỗ trợ chỉ cần đọc ticket và soạn phản hồi. Áp dụng nguyên tắc least privilege, thay đổi nào giảm rủi ro tốt nhất?",
      options: [
        ["Add logging to the refund and delete tools so misuse can be audited later.", "Thêm logging cho tool hoàn tiền và xóa để có thể audit việc lạm dụng sau này."],
        ["Remove the refund and delete tools from the agent's configuration entirely.", "Gỡ hẳn tool hoàn tiền và xóa khỏi cấu hình của agent."],
        ["Keep all tools but add a confirmation prompt before refunds and deletions.", "Giữ mọi tool nhưng thêm bước xác nhận trước khi hoàn tiền và xóa."],
        ["Replace the agent with a larger model that follows instructions more reliably.", "Thay agent bằng model lớn hơn, tuân thủ chỉ dẫn tốt hơn."]
      ],
      answer: "B",
      why: "Least privilege means removing capabilities the role does not require, eliminating the attack surface rather than monitoring or guarding it. Logging and confirmations are detective/compensating controls; model size is unrelated to authorization scope.",
      why_vi: "Least privilege nghĩa là loại bỏ năng lực mà vai trò không cần, xóa hẳn bề mặt tấn công thay vì giám sát hay canh chừng nó. Logging và bước xác nhận chỉ là control phát hiện/bù đắp; kích thước model không liên quan đến phạm vi phân quyền."
    },
    {
      domain: "Domain 2 — Models, Prompting & Context",
      q: "An application sends the same 8,000-token system prompt and policy document on every request, followed by a short, varying user message. Latency and cost are both concerns. Which optimization most directly addresses both?",
      q_vi: "Một ứng dụng gửi cùng system prompt và tài liệu chính sách 8.000 token ở mọi request, theo sau là tin nhắn người dùng ngắn và thay đổi. Cả latency và chi phí đều là mối lo. Tối ưu nào giải quyết trực tiếp nhất cả hai?",
      options: [
        ["Truncate the policy document to the first 1,000 tokens.", "Cắt tài liệu chính sách còn 1.000 token đầu."],
        ["Switch to the smallest available model regardless of task fit.", "Chuyển sang model nhỏ nhất bất kể mức độ phù hợp với tác vụ."],
        ["Place the static system prompt and policy before the dynamic content and enable prompt caching.", "Đặt system prompt và chính sách tĩnh trước nội dung động và bật prompt caching."],
        ["Move the policy document into a few-shot example block.", "Chuyển tài liệu chính sách vào khối ví dụ few-shot."]
      ],
      answer: "C",
      why: "Ordering stable content first and enabling prompt caching lets repeated prefixes be reused, reducing both time-to-first-token and per-request cost without discarding required context.",
      why_vi: "Đặt nội dung ổn định lên trước và bật prompt caching cho phép tái sử dụng phần prefix lặp lại, giảm cả time-to-first-token lẫn chi phí mỗi request mà không bỏ mất ngữ cảnh cần thiết."
    },
    {
      domain: "Domain 4 — Evaluation & Optimization",
      q: "A RAG system suddenly returns confident but incorrect answers after a document refresh, while latency and model version are unchanged. What is the most likely first place to investigate?",
      q_vi: "Một hệ thống RAG đột nhiên trả lời tự tin nhưng sai sau khi làm mới tài liệu, trong khi latency và phiên bản model không đổi. Nơi nào nên điều tra đầu tiên?",
      options: [
        ["The model weights have silently changed.", "Trọng số model đã âm thầm thay đổi."],
        ["The retrieval/indexing step is returning irrelevant or stale chunks.", "Bước retrieval/indexing đang trả về chunk không liên quan hoặc lỗi thời."],
        ["The temperature setting is too low.", "Thiết lập temperature quá thấp."],
        ["The context window has shrunk.", "Context window đã bị thu hẹp."]
      ],
      answer: "B",
      why: "Confident-but-wrong answers following a document refresh, with model and latency unchanged, point to retrieval feeding the model poor context — for example a broken re-index or mismatched embeddings.",
      why_vi: "Câu trả lời tự tin nhưng sai ngay sau khi làm mới tài liệu, trong khi model và latency không đổi, cho thấy retrieval đang cấp ngữ cảnh kém cho model — ví dụ re-index lỗi hoặc embedding không khớp."
    }
  ];

  const els = {
    main: document.getElementById("learnMain"),
    nav: document.getElementById("learnNav"),
    sidebar: document.getElementById("learnSidebar"),
    backdrop: document.getElementById("learnBackdrop"),
    menuBtn: document.getElementById("menuToggleBtn"),
    search: document.getElementById("searchInput"),
    progress: document.getElementById("progressSummary"),
    themeToggleBtn: document.getElementById("themeToggleBtn"),
    langToggleBtn: document.getElementById("langToggleBtn"),
    langToggleText: document.getElementById("langToggleText")
  };

  // Ngân hàng câu hỏi (nạp lười khi người học bấm "Luyện tập")
  let questionPool = null;

  // ==========================================================================
  // Storage helpers (localStorage có thể bị chặn, ví dụ private mode)
  // ==========================================================================
  function storageGet(key) {
    try { return localStorage.getItem(key); } catch (e) { return null; }
  }

  function storageSet(key, value) {
    try { localStorage.setItem(key, value); } catch (e) { /* ignore */ }
  }

  function getDone() {
    try { return new Set(JSON.parse(storageGet(PROGRESS_KEY) || "[]")); } catch (e) { return new Set(); }
  }

  function setDone(set) {
    storageSet(PROGRESS_KEY, JSON.stringify([...set]));
  }

  // ==========================================================================
  // Theme & language (dùng chung key với trang luyện đề)
  // ==========================================================================
  function initTheme() {
    const saved = storageGet("genai_exam_theme");
    const prefersDark = window.matchMedia && window.matchMedia("(prefers-color-scheme: dark)").matches;
    applyTheme(saved || (prefersDark ? "dark" : "light"));
    els.themeToggleBtn.addEventListener("click", () => {
      const next = document.documentElement.getAttribute("data-theme") === "dark" ? "light" : "dark";
      applyTheme(next);
      storageSet("genai_exam_theme", next);
    });
  }

  function applyTheme(theme) {
    document.documentElement.setAttribute("data-theme", theme);
    els.themeToggleBtn.innerHTML = theme === "dark" ? "☀️" : "🌙";
  }

  function initLanguage() {
    let show = storageGet("genai_exam_show_vi") !== "false";
    const apply = () => {
      document.body.classList.toggle("hide-translations", !show);
      els.langToggleBtn.classList.toggle("active", show);
      els.langToggleBtn.setAttribute("aria-pressed", show ? "true" : "false");
      els.langToggleText.textContent = show ? "Dịch TV: Bật" : "Dịch TV: Tắt";
    };
    apply();
    els.langToggleBtn.addEventListener("click", () => {
      show = !show;
      storageSet("genai_exam_show_vi", show ? "true" : "false");
      apply();
    });
  }

  // ==========================================================================
  // Helpers
  // ==========================================================================
  function esc(str) {
    if (str === undefined || str === null) return "";
    return String(str)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#039;");
  }

  function paragraphs(text, cls) {
    return String(text || "")
      .split(/\n\s*\n/)
      .filter((p) => p.trim())
      .map((p) => `<p class="${cls}">${esc(p.trim())}</p>`)
      .join("");
  }

  function biList(items) {
    if (!items || !items.length) return "";
    return `<ul class="bi-list">${items.map((it) => `
      <li>${esc(it.en)}${it.vi ? `<span class="vi-line">${esc(it.vi)}</span>` : ""}</li>`).join("")}
    </ul>`;
  }

  function allTopics() {
    const list = [];
    LESSONS.forEach((d) => d.topics.forEach((t) => list.push({ domain: d, topic: t })));
    return list;
  }

  function findDomain(num) {
    return LESSONS.find((d) => String(d.domain) === String(num));
  }

  function itemsPerSet(domain) {
    return Math.round((domain.weight / 100) * 63);
  }

  // ==========================================================================
  // Sidebar navigation
  // ==========================================================================
  function renderNav(activeId) {
    const done = getDone();
    const query = (els.search.value || "").trim().toLowerCase();
    let html = `<a class="nav-overview ${activeId === "overview" ? "active" : ""}" href="#overview">🏠 Tổng quan kỳ thi</a>`;
    let matches = 0;

    LESSONS.forEach((d) => {
      const topics = d.topics.filter((t) => !query || topicText(d, t).includes(query));
      if (query && !topics.length) return;
      matches += topics.length;
      html += `<div class="nav-domain">
        <a class="nav-domain-link ${activeId === `d${d.domain}` ? "active" : ""}" href="#d${d.domain}">
          <span>D${d.domain}. ${esc(d.title)}</span><span class="nav-weight">${d.weight}%</span>
        </a>
        ${topics.map((t) => `
          <a class="nav-topic ${activeId === t.id ? "active" : ""}" href="#${t.id}">
            <span class="nav-check">${done.has(t.id) ? "✓" : ""}</span>
            <span>${esc(t.title)}</span>
          </a>`).join("")}
      </div>`;
    });

    if (query && !matches) html += `<div class="nav-empty">Không tìm thấy bài học phù hợp.</div>`;
    els.nav.innerHTML = html;

    const total = allTopics().length;
    const pct = total ? Math.round((done.size / total) * 100) : 0;
    els.progress.innerHTML = `Đã học ${done.size}/${total} bài (${pct}%)
      <div class="progress-track"><div class="progress-fill" style="width:${pct}%"></div></div>`;
  }

  // Toàn bộ text của bài học, dùng cho ô tìm kiếm
  function topicText(d, t) {
    if (!t._search) {
      const parts = [d.title, d.title_vi, t.title, t.title_vi, t.objective];
      (t.sections || []).forEach((s) => parts.push(s.heading, s.heading_vi, s.body, s.body_vi));
      (t.terms || []).forEach((x) => parts.push(x.term, x.en, x.vi));
      (t.keyPoints || []).forEach((x) => parts.push(x.en, x.vi));
      t._search = parts.join(" ").toLowerCase();
    }
    return t._search;
  }

  // ==========================================================================
  // Pages
  // ==========================================================================
  function renderOverview() {
    const done = getDone();
    const maxWeight = Math.max(...LESSONS.map((d) => d.weight), 1);

    els.main.innerHTML = `
      <h2 class="page-title">Claude Certified Architect – Professional (CCAR-P)</h2>
      <div class="page-title-vi">Bài học song ngữ theo Exam Guide v1.0 — 7 domain, ${allTopics().length} objective</div>

      <section class="card">
        <div class="card-label">Exam at a glance · Thông tin kỳ thi</div>
        <div class="facts-grid">
          ${EXAM_FACTS.map((f) => `<div class="fact"><span class="val">${esc(f.val)}</span><span class="lbl">${esc(f.lbl)}</span></div>`).join("")}
        </div>
        <p class="en-text">Item format: multiple-choice and multiple-response items; each item states how many responses to select. Result: pass/fail with a scaled score plus percent-correct by domain.</p>
        <p class="vi-text">Dạng câu hỏi: chọn một và chọn nhiều đáp án; mỗi câu ghi rõ số đáp án cần chọn. Kết quả: đạt/không đạt kèm điểm quy đổi và tỷ lệ đúng theo từng domain.</p>
      </section>

      <section class="card">
        <div class="card-label">Exam blueprint · Cấu trúc đề thi</div>
        ${LESSONS.map((d) => `
          <a class="blueprint-row" href="#d${d.domain}">
            <span class="bp-name">D${d.domain}. ${esc(d.title)}<span class="vi-line">${esc(d.title_vi)} · ~${itemsPerSet(d)} câu</span></span>
            <span class="bp-bar"><span style="width:${(d.weight / maxWeight) * 100}%"></span></span>
            <span class="bp-val">${d.weight}%</span>
          </a>`).join("")}
      </section>

      <section class="card">
        <div class="card-label">How to use this page · Cách học</div>
        ${biList(STUDY_STEPS)}
      </section>

      <h3 style="margin:1.5rem 0 0.75rem;">Domains · Các domain</h3>
      <div class="domain-cards">
        ${LESSONS.map((d) => {
          const doneCount = d.topics.filter((t) => done.has(t.id)).length;
          return `<a class="domain-card" href="#d${d.domain}">
            <span class="dc-num">DOMAIN ${d.domain} · ${d.weight}%</span>
            <h4>${esc(d.title)}</h4>
            <span class="vi-line">${esc(d.title_vi)}</span>
            <div class="dc-meta">${d.topics.length} bài học · đã học ${doneCount}/${d.topics.length}</div>
          </a>`;
        }).join("")}
      </div>

      <h3 style="margin:1.75rem 0 0.75rem;">Official sample questions · Câu hỏi mẫu chính thức</h3>
      ${SAMPLES.map(renderSample).join("")}
    `;
  }

  function renderSample(s) {
    return `<section class="card">
      <div class="card-label">${esc(s.domain)}</div>
      <p class="en-text"><strong>${esc(s.q)}</strong></p>
      <p class="vi-text">${esc(s.q_vi)}</p>
      <ul class="bi-list">
        ${s.options.map((o, i) => `<li><strong>${"ABCD"[i]}.</strong> ${esc(o[0])}<span class="vi-line">${esc(o[1])}</span></li>`).join("")}
      </ul>
      <details class="sample-answer">
        <summary>Xem đáp án & giải thích</summary>
        <p class="en-text"><strong>Answer: ${s.answer}.</strong> ${esc(s.why)}</p>
        <p class="vi-text">${esc(s.why_vi)}</p>
      </details>
    </section>`;
  }

  function renderDomain(d) {
    const done = getDone();
    els.main.innerHTML = `
      <div class="breadcrumb"><a href="#overview">Tổng quan</a> › Domain ${d.domain}</div>
      <h2 class="page-title">Domain ${d.domain}: ${esc(d.title)}</h2>
      <div class="page-title-vi">${esc(d.title_vi)}</div>
      <span class="objective-badge">Tỷ trọng ${d.weight}% · ~${itemsPerSet(d)}/63 câu</span>

      <section class="card">
        <div class="card-label">Overview · Tổng quan</div>
        ${paragraphs(d.overview, "en-text")}
        ${paragraphs(d.overview_vi, "vi-text")}
      </section>

      <section class="card">
        <div class="card-label">Lessons · Bài học (theo objective của blueprint)</div>
        <ol class="topic-list">
          ${d.topics.map((t, i) => `
            <li><a href="#${t.id}">
              <span class="tl-num">${done.has(t.id) ? "✓" : `${d.domain}.${i + 1}`}</span>
              <span>${esc(t.title)}
                <span class="vi-line">${esc(t.title_vi)}</span>
                <span class="tl-obj">Objective: ${esc(t.objective)}</span>
              </span>
            </a></li>`).join("")}
        </ol>
      </section>
    `;
  }

  function renderTopic(d, t) {
    const list = allTopics();
    const idx = list.findIndex((x) => x.topic.id === t.id);
    const prev = list[idx - 1];
    const next = list[idx + 1];
    const isDone = getDone().has(t.id);
    const tableHtml = t.table && t.table.rows && t.table.rows.length ? `
      <section class="card">
        <div class="card-label">${esc(t.table.caption || "Comparison")}</div>
        ${t.table.caption_vi ? `<div class="vi-heading">${esc(t.table.caption_vi)}</div>` : ""}
        <div class="table-wrap"><table class="learn-table">
          <thead><tr>${(t.table.headers || []).map((h, i) => `<th>${esc(h)}${t.table.headers_vi && t.table.headers_vi[i] ? `<span class="vi-line">${esc(t.table.headers_vi[i])}</span>` : ""}</th>`).join("")}</tr></thead>
          <tbody>${t.table.rows.map((r) => `<tr>${r.map((c) => `<td>${esc(c)}</td>`).join("")}</tr>`).join("")}</tbody>
        </table></div>
      </section>` : "";

    els.main.innerHTML = `
      <div class="breadcrumb"><a href="#overview">Tổng quan</a> › <a href="#d${d.domain}">Domain ${d.domain}: ${esc(d.title)}</a></div>
      <h2 class="page-title">${esc(t.title)}</h2>
      <div class="page-title-vi">${esc(t.title_vi)}</div>
      <span class="objective-badge">🎯 Objective: ${esc(t.objective)}</span>

      ${(t.sections || []).map((s) => `
        <section class="card">
          <h3>${esc(s.heading)}</h3>
          ${s.heading_vi ? `<div class="vi-heading">${esc(s.heading_vi)}</div>` : ""}
          ${paragraphs(s.body, "en-text")}
          ${paragraphs(s.body_vi, "vi-text")}
          ${biList(s.bullets)}
        </section>`).join("")}

      ${tableHtml}

      ${t.keyPoints && t.keyPoints.length ? `
        <section class="card key-points">
          <div class="card-label">✅ Key points · Điểm cần nhớ</div>
          ${biList(t.keyPoints)}
        </section>` : ""}

      ${t.examTips && t.examTips.length ? `
        <section class="card exam-tips">
          <div class="card-label">🎯 Exam tips · Mẹo thi</div>
          ${biList(t.examTips)}
        </section>` : ""}

      ${t.terms && t.terms.length ? `
        <section class="card">
          <div class="card-label">📖 Terms · Thuật ngữ</div>
          <div class="terms-grid">
            ${t.terms.map((x) => `<div class="term"><strong>${esc(x.term)}</strong>${esc(x.en)}<span class="vi-line">${esc(x.vi)}</span></div>`).join("")}
          </div>
          ${t.sources && t.sources.length ? `<div class="sources">Nguồn tài liệu: ${t.sources.map((s) => `<code>${esc(s)}</code>`).join(", ")}</div>` : ""}
        </section>` : ""}

      <section class="card" id="practiceCard">
        <div class="card-label">📝 Practice · Luyện câu hỏi theo bài này</div>
        <p class="en-text">Questions are drawn from the CCAR-P mock exam bank for this objective.</p>
        <p class="vi-text">Câu hỏi được lấy từ ngân hàng đề thi thử CCAR-P, đúng objective của bài này.</p>
        <button type="button" class="btn btn-primary practice-check" id="startPracticeBtn">Luyện ${PRACTICE_SIZE} câu</button>
        <div id="practiceArea"></div>
      </section>

      <div class="page-actions">
        <button type="button" class="btn btn-secondary ${isDone ? "done" : ""}" id="markDoneBtn">${isDone ? "✓ Đã học xong" : "Đánh dấu đã học"}</button>
        <div style="display:flex; gap:0.5rem; flex-wrap:wrap;">
          ${prev ? `<a class="btn btn-secondary" href="#${prev.topic.id}">❮ Bài trước</a>` : ""}
          ${next ? `<a class="btn btn-primary" href="#${next.topic.id}">Bài tiếp ❯</a>` : `<a class="btn btn-primary" href="index.html?exam=ccarp">Làm đề thi thử ❯</a>`}
        </div>
      </div>
    `;

    document.getElementById("markDoneBtn").addEventListener("click", () => {
      const done = getDone();
      if (done.has(t.id)) done.delete(t.id); else done.add(t.id);
      setDone(done);
      renderTopic(d, t);
      renderNav(t.id);
    });
    document.getElementById("startPracticeBtn").addEventListener("click", () => startPractice(t));
  }

  // ==========================================================================
  // Topic practice (dùng câu hỏi từ 10 bộ đề)
  // ==========================================================================
  function loadScript(src) {
    return new Promise((resolve, reject) => {
      const s = document.createElement("script");
      s.src = src;
      s.onload = resolve;
      s.onerror = reject;
      document.head.appendChild(s);
    });
  }

  async function loadQuestionPool() {
    if (questionPool) return questionPool;
    const sets = MANIFEST.length ? MANIFEST : Array.from({ length: 10 }, (_, i) => ({
      jsFile: `set_${i + 1}.js`, jsVar: `QUIZ_DATA_CCARP_SET_${i + 1}`
    }));
    await Promise.all(sets.map((s) => (window[s.jsVar] ? null : loadScript(`CCAR-P/${s.jsFile}`).catch(() => null))));
    questionPool = [];
    sets.forEach((s) => (window[s.jsVar] || []).forEach((q) => questionPool.push(q)));
    return questionPool;
  }

  async function startPractice(t) {
    const area = document.getElementById("practiceArea");
    area.innerHTML = `<p class="en-text">Đang tải câu hỏi…</p>`;
    const pool = (await loadQuestionPool()).filter((q) => q.lessonId === t.id);
    if (!pool.length) {
      area.innerHTML = `<p class="en-text">Chưa có câu hỏi cho bài này.</p>`;
      return;
    }
    const picked = pool.slice().sort(() => Math.random() - 0.5).slice(0, PRACTICE_SIZE);
    document.getElementById("startPracticeBtn").textContent = `Đổi ${PRACTICE_SIZE} câu khác`;
    area.innerHTML = picked.map((q, i) => renderPracticeQuestion(q, i)).join("");
    picked.forEach((q, i) => bindPracticeQuestion(q, i));
  }

  function renderPracticeQuestion(q, i) {
    const multi = q.answer.length > 1;
    return `<div class="practice-q" id="pq-${i}">
      <div class="q-title-en"><strong>${i + 1}.</strong> ${esc(q.question)}</div>
      ${q.question_vi ? `<div class="q-title-vi vi-text">${esc(q.question_vi)}</div>` : ""}
      <div class="practice-opts">
        ${q.options.map((o) => `
          <label class="practice-opt" data-key="${o.key}">
            <input type="${multi ? "checkbox" : "radio"}" name="pq-${i}" value="${o.key}">
            <span><strong>${o.key})</strong> ${esc(o.text)}
              ${o.text_vi ? `<span class="option-text-vi vi-line">${esc(o.text_vi)}</span>` : ""}</span>
          </label>`).join("")}
      </div>
      <button type="button" class="btn btn-secondary practice-check">Kiểm tra${multi ? ` (chọn ${q.answer.length})` : ""}</button>
      <div class="practice-result"></div>
    </div>`;
  }

  function bindPracticeQuestion(q, i) {
    const box = document.getElementById(`pq-${i}`);
    box.querySelector(".practice-check").addEventListener("click", () => {
      const chosen = [...box.querySelectorAll("input:checked")].map((x) => x.value).sort();
      const correct = q.answer.slice().sort();
      const ok = chosen.length === correct.length && chosen.every((k, j) => k === correct[j]);
      box.querySelectorAll(".practice-opt").forEach((el) => {
        const key = el.dataset.key;
        el.classList.toggle("correct", correct.includes(key));
        el.classList.toggle("wrong", chosen.includes(key) && !correct.includes(key));
      });
      box.querySelector(".practice-result").innerHTML = `
        <span class="${ok ? "verdict-ok" : "verdict-bad"}">${ok ? "✓ Chính xác" : `✗ Chưa đúng — đáp án: ${correct.join(", ")}`}</span>
        <p class="en-text">💡 ${esc(q.explanation)}</p>
        ${q.explanation_vi ? `<p class="vi-text">${esc(q.explanation_vi)}</p>` : ""}`;
    });
  }

  // ==========================================================================
  // Routing
  // ==========================================================================
  function route() {
    const hash = decodeURIComponent(window.location.hash.replace(/^#/, "")) || "overview";
    closeMenu();

    if (!LESSONS.length) {
      els.main.innerHTML = `<p class="learn-loading">Chưa có dữ liệu bài học (CCAR-P/lessons/lessons.js). Hãy chạy <code>python build_ccarp.py</code>.</p>`;
      return;
    }

    const topicMatch = hash.match(/^d(\d+)-t\d+$/);
    const domainMatch = hash.match(/^d(\d+)$/);
    let activeId = "overview";

    if (topicMatch) {
      const d = findDomain(topicMatch[1]);
      const t = d && d.topics.find((x) => x.id === hash);
      if (t) {
        renderTopic(d, t);
        activeId = t.id;
      } else {
        renderOverview();
      }
    } else if (domainMatch && findDomain(domainMatch[1])) {
      renderDomain(findDomain(domainMatch[1]));
      activeId = hash;
    } else {
      renderOverview();
    }

    renderNav(activeId);
    window.scrollTo({ top: 0 });
  }

  function openMenu() {
    els.sidebar.classList.add("open");
    els.backdrop.classList.add("active");
  }

  function closeMenu() {
    els.sidebar.classList.remove("open");
    els.backdrop.classList.remove("active");
  }

  function init() {
    initTheme();
    initLanguage();
    els.menuBtn.addEventListener("click", openMenu);
    els.backdrop.addEventListener("click", closeMenu);
    els.search.addEventListener("input", () => {
      const hash = window.location.hash.replace(/^#/, "") || "overview";
      renderNav(hash);
    });
    window.addEventListener("hashchange", route);
    route();
  }

  document.addEventListener("DOMContentLoaded", init);
})();
